import{_ as a,o as u,c as r,a3 as s,j as e,a as n}from"./chunks/framework.z_KJ15Ep.js";const p=JSON.parse('{"title":"Zeugnispakete nach Schulform auswählen","description":"","frontmatter":{"title":"Zeugnispakete nach Schulform auswählen","source_pageid":1621,"source_revision":6809},"headers":[],"relativePath":"reporting/zeugnisformulare/zeugnispakete-auf-github.md","filePath":"reporting/zeugnisformulare/zeugnispakete-auf-github.md"}'),t={name:"reporting/zeugnisformulare/zeugnispakete-auf-github.md"};function l(o,i,h,g,f,d){return u(),r("div",null,[...i[0]||(i[0]=[s('<h1 id="zeugnispakete-nach-schulform-auswahlen" tabindex="-1">Zeugnispakete nach Schulform auswählen <a class="header-anchor" href="#zeugnispakete-nach-schulform-auswahlen" aria-label="Permalink to &quot;Zeugnispakete nach Schulform auswählen&quot;">​</a></h1><p>Wählen Sie das Paket für Ihre Schulform. Jede Veröffentlichung enthält eine Änderungshistorie, anhand derer Sie den bereitgestellten Stand beurteilen können.</p><h2 id="zeugnispakete-auf-github" tabindex="-1">Zeugnispakete auf GitHub <a class="header-anchor" href="#zeugnispakete-auf-github" aria-label="Permalink to &quot;Zeugnispakete auf GitHub&quot;">​</a></h2><p>Für SchILD-NRW 3 werden alle Zeugnisse als ZIP-Paketdatei auf GitHub angeboten. Sie finden die Zeugnispakete im jeweiligen schulformspezifischen Release-Bereich. Zu jeder Veröffentlichung (Release) finden Sie dort auch eine Änderungshistorie anhand derer Sie entscheiden können, ob sich ein Download für Ihre Schulform lohnt.</p><h2 id="links-zu-den-zeugnispaketen-auf-github" tabindex="-1">Links zu den Zeugnispaketen auf GitHub <a class="header-anchor" href="#links-zu-den-zeugnispaketen-auf-github" aria-label="Permalink to &quot;Links zu den Zeugnispaketen auf GitHub&quot;">​</a></h2><ul><li>➡️ <a href="https://github.com/SVWS-NRW/Schild-NRW-3-Zeugnisse-GS/releases" target="_blank" rel="noreferrer">Zeugnisse - Primarstufe</a></li></ul><p>Textzeugnis mit Floskeln, Noten-, Hybrid- und Ankreuzzeugnis, Lernstandsbericht für die Primarstufe</p><ul><li>➡️ Zeugnisse - Sekundarstufe I (im Aufbau)</li></ul><p>Zeugnisse, Abschluss-, Abgangs-, Überweisungs- und Inklusionszeugnisse, Lernstandsberichte für alle Schulformen der Sekundarstufe I</p><ul><li>➡️ Zeugnisse - Sekundarstufe II (im Aufbau)</li></ul><p>Zeugnis EF, Laufbahnbescheinigung, Abiturzeugnis und Bescheinigungen für die Sekundarstufe II</p><ul><li>➡️ <a href="https://github.com/SVWS-NRW/Schild-NRW-3-Zeugnisse-BK/releases" target="_blank" rel="noreferrer">Zeugnisse - Berufskolleg</a></li></ul><p>Zeugnisse für alle Gliederungen von Anlage A bis Anlage E für Berufskollegs</p><ul><li>➡️ <a href="https://github.com/SVWS-NRW/Schild-NRW-3-Zeugnisse-GS/releases" target="_blank" rel="noreferrer">Zeugnisse - Weiterbildungskolleg</a></li></ul><p>Zeugnis, Abgangs- und Abschlusszeugnis, Bescheinigungen für Weiterbildungskollegs</p>',15),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),n("Hinweis")]),e("p",null,[n("Erfahren Sie in folgendem Artikel Schritt für Schritt, wie Sie "),e("a",{href:"/reporting/zeugnisformulare/zeugnisformulare-herunterladen-und-aktualisieren.html"},"Zeugnisformulare herunterladen und bereitstellen"),n(".")])],-1),e("hr",null,null,-1),e("p",null,[e("a",{href:"https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Zeugnispakete_auf_GitHub",target:"_blank",rel:"noreferrer"},"Originalartikel im Wiki"),n(" · Quellrevision 6809.")],-1)])])}const k=a(t,[["render",l]]);export{p as __pageData,k as default};
